// Create persists in under parent and returns the stored record.
func (r *GormQuoteRepository) Create(ctx context.Context, parent string, in *salespbv1.Quote) (*salespbv1.Quote, error) {
	parentIDs, err := repox.SplitName(parent, "venues")
	if err != nil {
		return nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "venues", "quotes")
		if err != nil {
			return nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*salespbv1.Quote)
	in.Name = FormatQuoteName(parentIDs[0], id)
	// The id is unique only under the parent, so the row is keyed by a
	// surrogate of its own: the id itself only when it was minted here.
	id = rowID
	if h := r.Hooks.BeforeCreate; h != nil {
		if err := h(ctx, in); err != nil {
			return nil, err
		}
	}
	if err := checkQuoteRequired(in); err != nil {
		return nil, err
	}
	m := sales.QuoteFromProto(in)
	m.ID = id
	m.Name = in.GetName()
	m.VenueID = parentIDs[0]
	if v := in.GetContact(); v != "" {
		m.ContactID = repox.LastSegment(v)
	}
	if v := in.GetLead(); v != "" {
		m.LeadID = repox.Ptr(repox.LastSegment(v))
	}
	m.Etag = repox.Ptr(repox.NewULID())
	if err := r.store(r.DB).Create(ctx, m); err != nil {
		return nil, repox.MapGormErr(err)
	}
	return r.get(ctx, m.Name)
}

