func (r *GormQuoteRepository) list(ctx context.Context, scope *gorm.DB, in repox.ListInput) ([]*salespbv1.Quote, string, error) {
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	eng := filterx.Gorm[sales.Quote](sales.QuoteFilterSpec)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	if err := repox.CheckReadMask((*salespbv1.Quote)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	rows, next, err := eng.List(ctx, r.reads(scope, in), filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*salespbv1.Quote, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i])
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

